// Pull doc inventory: registre, PIA, mentions, politique, dpa
const cfg = $json;
const types = ['registre_traitement','pia','mentions_legales','politique_confidentialite'];
const rows = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://auth.purama.dev/rest/v1/legal_documents?user_id=eq.${cfg.user_id}&type=in.(${types.join(',')})&select=type,title,status,updated_at`,
  headers: {
    apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
    'Accept-Profile': 'purama_ai',
  },
  json: true,
});
const inventory = {};
for (const t of types) inventory[t] = rows.find((r) => r.type === t) || null;
return [{ json: { ...cfg, _inventory: inventory } }];

