const cfg = $('Inventory').item.json;
const raw = $json.content?.[0]?.text || '{}';
let a = { score: 50, summary: '', missing: [], outdated: [], recommendations: [] };
try { const m = raw.match(/\{[\s\S]*\}/); a = { ...a, ...JSON.parse(m ? m[0] : raw) }; } catch(e) {}
const severity = a.score < 50 ? 'urgent' : a.score < 75 ? 'action_required' : 'info';
const priority = a.score < 50 ? 'urgent' : a.score < 75 ? 'high' : 'normal';
return [{ json: {
  // Veille insert payload
  _insert: {
    user_id: cfg.user_id,
    title: `Audit RGPD trimestriel · ${a.score}/100`,
    type: 'alert',
    category: 'rgpd',
    severity,
    summary: a.summary || 'Audit RGPD complété',
    impact: (a.missing && a.missing.length ? `Manquants: ${a.missing.join(', ')}` : '') + (a.outdated && a.outdated.length ? ` · À jour: ${a.outdated.join(', ')}` : ''),
    action_required: (a.recommendations || []).join(' · '),
    source_name: 'Purama Legal Agent',
    reference: 'Audit RGPD trimestriel',
  },
  // Push payload
  _notif: {
    user_id: cfg.user_id,
    agent_type: 'legal',
    title: `🛡️ Audit RGPD : ${a.score}/100`,
    body: a.summary || 'Audit RGPD trimestriel disponible',
    action_type: 'review',
    action_url: '/dashboard/legal-agent/veille',
    priority,
    channels: ['push', 'in_app'],
  },
} }];
